  const savedProfile = readStoredJson('jupiter_user', null);
  const savedAuthToken = localStorage.getItem('jupiter_auth_token');
  const savedSessionCandidate = isProfileRecord(savedProfile) && savedAuthToken ? savedProfile : null;
