        // Invalidate the screen being left before rendering its predecessor.
        // The status token remains persisted so the next deliberate Register
        // entry can hydrate the canonical server stage.
        nextAuthStateGeneration();
        stopRegistrationPolling();
        resetOtpUiState();
        pendingRegistrationGrant = null;
        pendingRegistration = null;
