  const centerBrand = document.querySelector('.center-brand');
  const loadLevelEl = document.getElementById('load-level');
  const loadDetailEl = document.getElementById('load-detail');

  const handleOfflineUI = () => {
      if (netStatusEl) netStatusEl.className = 'internet-status offline';
      if (netIcon) netIcon.className = 'ph-fill ph-wifi-slash';
      if (netText) netText.innerText = 'No Internet';
      if (msgInput) {
        msgInput.disabled = true;
        msgInput.value = '';
        msgInput.placeholder = 'Please connect to the internet first.';
      }
      if (micButton) micButton.style.display = 'none';
      if (sendButton) sendButton.style.display = 'none';
      centerBrand?.classList.add('brand-offline');
      
      
      
  };

  const updateNetworkStatus = async () => {
    if (navigator.onLine) {
      let ping = 0;
      if (navigator.connection && navigator.connection.rtt) {
         ping = navigator.connection.rtt;
      } else {
         const start = performance.now();
         try {
            await fetch('https://www.google.com/favicon.ico', { mode: 'no-cors', cache: 'no-store' });
            ping = performance.now() - start;
         } catch(e) {
            ping = 9999;
         }
      }
      
      let iconClass = 'ph-fill ph-wifi-high';
      let text = 'Connected';
      if (ping > 800) {
        iconClass = 'ph-fill ph-wifi-none';
        text = 'Poor Connection';
      } else if (ping > 400) {
        iconClass = 'ph-fill ph-wifi-low';
        text = 'Slow Connection';
      } else if (ping > 150) {
        iconClass = 'ph-fill ph-wifi-medium';
        text = 'Good Connection';
      }
      
      if (ping === 9999) {
        handleOfflineUI();
        return;
      }

      if (netStatusEl) netStatusEl.className = 'internet-status online';
      if (netIcon) netIcon.className = iconClass;
      if (netText) netText.innerText = text;
      
      if (msgInput) {
        msgInput.disabled = false;
        msgInput.placeholder = 'Type here to chat...';
      }
      if (micButton) micButton.style.display = 'block';
      if (sendButton) sendButton.style.display = 'flex'; // It's flex now
      updateComposerAction();
      centerBrand?.classList.remove('brand-offline');
      
      
      
    } else {
      handleOfflineUI();
    }
  };

  // Elements
  const sidebar = document.getElementById('sidebar');
