  const liveCallKeyboardToggle = document.getElementById('live-keyboard-toggle');
  const liveVoiceTitle = document.getElementById('live-voice-title');
  const liveVoiceSubtitle = document.getElementById('live-voice-subtitle');
  // ── Live media: edge aura, original cues, camera visual input and the Jupiter-only camera transcript ──────────
  // Isolated from microphone capture and turn ownership: the camera requests VIDEO ONLY and frames travel as a
  // separate 'video_frame' stream on the native socket (never activity_start/activity_end).
  const liveCameraVideo = document.getElementById('live-camera-video');
  const liveCameraToggle = document.getElementById('live-camera-toggle');
  const liveCameraTools = document.getElementById('live-camera-tools');
  const liveCameraFlip = document.getElementById('live-camera-flip');
  const liveCameraTorch = document.getElementById('live-camera-torch');
  const liveVisualLabelsOverlay = document.getElementById('live-visual-labels');
  // ── On-demand visual grounding (Camera Live) ─────────────────────────────────────────────────────────────────
  // No toggle, no preference, no polling and no detector request from here. The backend grounds ONE canonical frame
  // only when the user explicitly asks Jupiter to mark/box/label/highlight/point out/locate something and sends one
  // `visual_grounding` event. This draws that temporary box, VERIFIES it is on screen and reports the outcome back
  // (`visual_render_result`): Jupiter's single answer is composed only after that confirmation.
  const liveGroundingGeometry = () => {
    const video = liveCameraVideo;
    if (!video || !liveMedia.cameraOn || !video.videoWidth) return null;
    const rect = video.getBoundingClientRect();
    return { videoWidth: video.videoWidth, videoHeight: video.videoHeight, viewWidth: rect.width, viewHeight: rect.height,
      mirrored: video.classList.contains('preview-flipped') };
  };
  let liveGroundingOverlay = null;
  const groundingOverlay = () => {
    if (!liveGroundingOverlay && window.JupiterVisualLabels?.createGroundingOverlay) {
      liveGroundingOverlay = window.JupiterVisualLabels.createGroundingOverlay({
        overlay: liveVisualLabelsOverlay, getGeometry: liveGroundingGeometry,
        onTelemetry: (fields) => window.__traceLiveVoice?.('visual-grounding', fields) });
    }
    return liveGroundingOverlay;
  };
  window.__jupiterLiveVisualGrounding = (event) => {
    if (!event || !liveVoiceSession) return false;
    if (event.type === 'visual_grounding_started') {
      window.__traceLiveVoice?.('visual-grounding', { visualGroundingRequested: 1, visualGroundingAction: String(event.action || '') });
      if (event.logical_turn_id && event.logical_turn_id === liveVoiceSession.nativeTurn?.id) window.__jupiterLiveThinkingOnAccept?.();
      return true;
    }
    const outcome = !liveMedia.cameraOn && event.action !== 'clear'
      ? { rendered: false, reason: 'camera_off' }                        // camera off: nothing to draw on
      : (groundingOverlay()?.show(event) || { rendered: false, reason: 'overlay_unavailable' });
    if (event.request_id) {
      const socket = liveVoiceNativeSocket;
      try {
        if (socket?.readyState === WebSocket.OPEN) {
          socket.send(JSON.stringify({ type: 'visual_render_result', request_id: String(event.request_id).slice(0, 32),
            rendered: Boolean(outcome.rendered), reason: String(outcome.reason || '').slice(0, 40) }));
        }
      } catch (_) { /* the backend's bounded wait treats silence as "not visible" */ }
    }
    return Boolean(outcome.rendered);
  };
  const sendLiveCameraState = () => {
    const socket = liveVoiceNativeSocket;
    if (!socket || socket.readyState !== WebSocket.OPEN) return false;
    try {
      socket.send(JSON.stringify({ type: 'camera_state', on: Boolean(liveMedia.cameraOn),
        mirrored: Boolean(liveMedia.cameraOn && liveCameraVideo?.classList.contains('preview-flipped')) }));
      return true;
    } catch (_) { return false; }
  };
  const liveCameraTranscriptToggle = document.getElementById('live-camera-transcript-toggle');
  const liveCameraNotice = document.getElementById('live-camera-notice');
  const liveCameraUnavailable = document.getElementById('live-camera-unavailable');
  const liveCameraUnavailableDetail = document.getElementById('live-camera-unavailable-detail');
  const liveCameraRetry = document.getElementById('live-camera-retry');
  // Camera wanted but not healthy (shutter closed, muted/ended track, busy device): a lightweight recoverable panel.
  // The controller keeps trying (bounded) and clears this automatically when real frames resume.
  const setLiveCameraUnavailable = (unavailable, message = '') => {
    liveVoiceOverlay?.classList.toggle('live-camera-unavailable-state', Boolean(unavailable));
    if (liveCameraUnavailable) liveCameraUnavailable.hidden = !unavailable;
    if (liveCameraUnavailableDetail && unavailable) {
      liveCameraUnavailableDetail.textContent = String(message || 'Open your camera shutter or check permission.')
        .replace(/^Camera unavailable\.\s*/, '');
    }
  };
  const liveMedia = { aura: null, sounds: null, camera: null, overlay: null, sessionId: '', cueSeq: 0, cameraOn: false, noticeTimer: null };
  const showLiveCameraNotice = (message) => {
    if (!liveCameraNotice) return;
    window.clearTimeout(liveMedia.noticeTimer);
    liveCameraNotice.textContent = String(message || '');
    liveCameraNotice.hidden = !message;
    if (message) liveMedia.noticeTimer = window.setTimeout(() => { liveCameraNotice.hidden = true; }, 6000);
  };
  // Jupiter's own UI cues (entry chime, mute/camera tones) are Jupiter-owned audio exactly like its speech: while a
  // cue plays (+ room tail) the microphone must not treat it as user speech. Root cause of a phantom turn submitted
  // 0.3 s after connect (entry chime → VAD → activity → model silence + Whisper prompt echo).
  const LIVE_CUE_GUARD_MS = 900;
  const armLiveCueGuard = () => { window.__jupiterLiveCueGuardUntil = performance.now() + LIVE_CUE_GUARD_MS; };
  const liveCue = (cue) => { armLiveCueGuard(); return liveMedia.sounds?.play(cue, `${liveMedia.sessionId}:${cue}:${++liveMedia.cueSeq}`); };
  // ── Transcript view: ONE session-scoped switch, hidden whenever Live opens ───────────────────────────────────
  // Speech/screen mode: the chat-style transcript panel (the orb shrinks below it). Camera mode: the compact strip of
  // Jupiter's current response, so the camera subject stays clear. Toggling never touches the Live session.
  const liveTranscriptView = { visible: false, prefVisible: null };
  const syncLiveTranscriptToggle = () => {
    const visible = Boolean(liveTranscriptView.visible);
    liveCameraTranscriptToggle?.setAttribute('aria-pressed', String(visible));
    liveCameraTranscriptToggle?.setAttribute('aria-label', visible ? 'Hide transcript' : 'Show transcript');
  };
  window.__jupiterSetLiveTranscript = (visible) => (liveVoiceOpen ? setLiveTranscriptVisible(Boolean(visible), 'voice_request') : null);
  const setLiveTranscriptVisible = (visible, reason = 'user') => {
    liveTranscriptView.visible = Boolean(visible);
    liveVoiceOverlay?.classList.toggle('live-transcript-visible', liveTranscriptView.visible);
    liveMedia.overlay?.setVisible(liveTranscriptView.visible);
    syncLiveTranscriptToggle();
    syncLiveStageGeometry();
    if (liveTranscriptView.visible) window.requestAnimationFrame?.(() => window.__jupiterFollowLiveTranscript?.());
    window.__traceLiveVoice?.('transcript-view', { action: liveTranscriptView.visible ? 'shown' : 'hidden', reason });
    return liveTranscriptView.visible;
  };
  // Orb placement needs the dock's real top edge (the composer can grow): measured, never guessed.
  let liveStageObserver = null;
