  // Copy/Share); every other message keeps hold-for-menu. Nothing is copied automatically.
  const exitMessageSelectMode = () => {
    const target = messageSelectModeTarget;
    messageSelectModeTarget = null;
    messageSelectModeObserver?.disconnect();
    messageSelectModeObserver = null;
    if (!target) return false;
    target.classList.remove('message-select-mode');
    try {
      const selection = window.getSelection?.();
      if (selection && !selection.isCollapsed && target.contains(selection.anchorNode)) selection.removeAllRanges();
    } catch (_) {}
    return true;
  };
