    if (!messageElement || !record) return;
    if (reportAttachments.length) void discardReportAttachments();
    reportMessageTarget = { messageElement, record };
    reportFormTitle && (reportFormTitle.textContent = 'Report this response');
    if (reportFormContext) {
      reportFormContext.textContent = 'This report will include the selected Jupiter response.';
      reportFormContext.classList.remove('hidden');
    }
    reportForm?.reset();
    reportAttachments = [];
