  document.getElementById('report-form-close')?.addEventListener('click', closeReportForm);
  reportFormModal?.addEventListener('click', (event) => { if (event.target === reportFormModal) closeReportForm(); });
  reportAttachmentInput?.addEventListener('change', async () => {
    const files = [...(reportAttachmentInput.files || [])];
    reportAttachmentInput.value = '';
    for (const file of files) {
      if (reportAttachments.length >= 8) {
        showToastError('Attach at most 8 files to one report.');
        break;
      }
      let previewUrl = '';
      try {
        if (file.size > (String(file.type || '').startsWith('video/') ? 100 : 10) * 1024 * 1024) {
          throw new Error(String(file.type || '').startsWith('video/') ? 'Videos must be 100 MB or smaller.' : 'Report attachments must be 10 MB or smaller.');
        }
        const baseUrl = await resolveBackendOrigin();
        if (!baseUrl) throw new Error('Jupiter is offline.');
        const response = await fetch(`${baseUrl}/api/reports/attachments`, {
          method: 'POST',
          headers: withClientHeaders({ 'Content-Type': 'application/json', Authorization: `Bearer ${localStorage.getItem('jupiter_auth_token') || ''}` }),
          body: JSON.stringify({ filename: file.name, mime_type: file.type, data_base64: await fileToBase64(file) })
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(data.detail || 'Jupiter could not add that report attachment.');
        const attachment = normalizedAttachments([data.attachment])[0];
        if (!attachment) throw new Error('Jupiter could not stage that report attachment.');
        if (SAFE_REPORT_IMAGE_PREVIEW_MIMES.has(String(file.type || '').toLowerCase())) {
          previewUrl = URL.createObjectURL(file);
          attachment.previewUrl = previewUrl;
        }
        reportAttachments.push(attachment);
        renderReportAttachments();
      } catch (error) {
        if (previewUrl) URL.revokeObjectURL(previewUrl);
        showToastError(error?.message || 'Unable to add that report attachment.');
      }
    }
  });
