    // ID only after the response caused the backend's initial `default` P4
    // state to be stranded away from the chat used by the next turn.
    ensureActiveChatId();
    const clientMessageId = `msg-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const pendingCapabilityMetadata = {
      requested: capabilitiesForMessage,
      detected: [],
      executed: [],
      ignored_requested: [],
      transcript_provenance: transcriptProvenanceForMessage
    };
    if (transcriptProvenanceForMessage) {
      void queueComposerRecognitionLearning(transcriptProvenanceForMessage, text);
    }
    addMessage(messageText, 'user', null, null, displayedAttachmentsForMessage, clientMessageId, null, null, pendingCapabilityMetadata);
    messageInput.value = '';
    pendingComposerTranscriptProvenance = null;
    resizeComposer();
    stagedAttachments.forEach((attachment) => {
      if (attachment.previewUrl) URL.revokeObjectURL(attachment.previewUrl);
    });
    stagedAttachments = [];
    editingReferenceAttachment = null;
    selectedCapabilities.clear();
    pendingQuestionAnswer = null;
    pendingTtsRegeneration = null;
