    if (currentStatus && gmailIsConnected(currentStatus)) {
      resolvePendingGmailState('', { removeCard: true, connected: true });
      return;
    }
    // A transient status/refresh check must not resurrect an obsolete Connect
    // action. Wait for an authoritative state instead of trusting old UI data.
    if (!currentStatus || gmailConnectionState(currentStatus) === 'REFRESHING') return;
    const authorizationRequired = state.status === 'awaiting_authorization';
    const currentConnection = gmailConnectionState(currentStatus);
    const currentCategory = {
      NOT_CONNECTED: 'USER_NOT_CONNECTED',
      SCOPE_MISSING: 'SCOPE_MISSING',
      AUTH_REVOKED: 'AUTH_REVOKED',
      REFRESH_FAILED: 'REFRESH_FAILED'
    }[currentConnection];
