      type: 'gmail_status',
      reply: authorizationRequired
        ? (currentConnection === 'NOT_CONNECTED' ? 'Connect Gmail to complete this request.' : 'Reconnect Gmail to complete this request.')
        : 'The previous Gmail request can be retried.',
      gmail_state: currentStatus.state || state.connectionState,
      gmail_error_category: authorizationRequired
