    const lastVoiced = Number.isInteger(session?.lastVoicedFrame) ? session.lastVoicedFrame : -1;
    if (lastVoiced < 0 || !frames?.length) return frames;
    const frameMs = (frames[0].length / Math.max(1, Number(session.sampleRate) || 16000)) * 1000;
    const tail = Math.ceil(NORMAL_STT_TRAILING_PAD_MS / Math.max(1, frameMs));
