      document.getElementById('auth-email').value = resume.email;
      document.getElementById('auth-request-username').value = username;
      document.getElementById('auth-username').value = username;
      document.getElementById('auth-step-access-request').classList.add('hidden');
      document.getElementById('auth-step-registration-approved').classList.add('hidden');
      document.getElementById('auth-step-1').classList.add('hidden');
      document.getElementById('auth-step-2').classList.add('hidden');
      document.getElementById('auth-step-3').classList.add('hidden');
